mapper.select:
SELECT id, name, description, price, currency, stock, category, image_url, version, created_at, updated_at
FROM products
WHERE category = #{category}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT id, name, description, price, currency, stock, category, image_url, version, created_at, updated_at
FROM products
WHERE id = #{id}

mapper.update:
UPDATE products
SET stock   = stock - #{quantity},
    version = version + 1
WHERE id = #{id}
  AND version = #{version}
  AND stock >= #{quantity}
